/****************************************************************************
 * Throwaway probe: does libjpeg-turbo's classic compression API build and
 * link for this ARM target, and what does it cost in flash?
 *
 * Not part of the driver.  turbojpeg.c (and therefore tjCompressFromYUV) is
 * excluded by external/libjpeg-turbo/CMakeLists.txt, which globs only j*.c,
 * so the driver has to drive jpeg_write_raw_data() directly -- this probe
 * exercises exactly that path so the measurement is meaningful.
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <jpeglib.h>

#define W 64
#define H 32

int main(int argc, char *argv[])
{
  struct jpeg_compress_struct cinfo;
  struct jpeg_error_mgr jerr;
  unsigned char *out = NULL;
  unsigned long outlen = 0;
  unsigned char *y;
  unsigned char *u;
  unsigned char *v;
  JSAMPROW yrow[16];
  JSAMPROW urow[8];
  JSAMPROW vrow[8];
  JSAMPARRAY planes[3];
  int i;

  y = malloc(W * H);
  u = malloc(W * H / 4);
  v = malloc(W * H / 4);
  if (y == NULL || u == NULL || v == NULL)
    {
      printf("probe: oom\n");
      return 1;
    }

  memset(y, 128, W * H);
  memset(u, 100, W * H / 4);
  memset(v, 150, W * H / 4);

  cinfo.err = jpeg_std_error(&jerr);
  jpeg_create_compress(&cinfo);
  jpeg_mem_dest(&cinfo, &out, &outlen);

  cinfo.image_width = W;
  cinfo.image_height = H;
  cinfo.input_components = 3;
  cinfo.in_color_space = JCS_YCbCr;
  jpeg_set_defaults(&cinfo);
  jpeg_set_colorspace(&cinfo, JCS_YCbCr);

  /* 4:2:0 -- Y is sampled 2x2, the chroma planes 1x1. */

  cinfo.comp_info[0].h_samp_factor = 2;
  cinfo.comp_info[0].v_samp_factor = 2;
  cinfo.comp_info[1].h_samp_factor = 1;
  cinfo.comp_info[1].v_samp_factor = 1;
  cinfo.comp_info[2].h_samp_factor = 1;
  cinfo.comp_info[2].v_samp_factor = 1;

  cinfo.raw_data_in = TRUE;
  jpeg_set_quality(&cinfo, 80, TRUE);
  jpeg_start_compress(&cinfo, TRUE);

  planes[0] = yrow;
  planes[1] = urow;
  planes[2] = vrow;

  /* With 4:2:0 each pass consumes 16 luma rows and 8 rows per chroma plane. */

  while (cinfo.next_scanline < cinfo.image_height)
    {
      for (i = 0; i < 16; i++)
        {
          unsigned int row = cinfo.next_scanline + i;

          if (row >= H)
            {
              row = H - 1;
            }

          yrow[i] = y + (size_t)row * W;
        }

      for (i = 0; i < 8; i++)
        {
          unsigned int row = cinfo.next_scanline / 2 + i;

          if (row >= H / 2)
            {
              row = H / 2 - 1;
            }

          urow[i] = u + (size_t)row * (W / 2);
          vrow[i] = v + (size_t)row * (W / 2);
        }

      jpeg_write_raw_data(&cinfo, planes, 16);
    }

  jpeg_finish_compress(&cinfo);
  jpeg_destroy_compress(&cinfo);

  printf("probe: %dx%d -> %lu bytes, SOI=%02x%02x EOI=%02x%02x\n",
         W, H, outlen,
         out[0], out[1], out[outlen - 2], out[outlen - 1]);

  free(out);
  free(y);
  free(u);
  free(v);
  return 0;
}

