    }
  else if (strcmp(argv[1], "info") == 0)
    {
      return jpeg_test_info() < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
    }

  jpeg_test_usage();
  return EXIT_FAILURE;
}

