sub("""#include <nuttx/kmalloc.h>
#include <nuttx/video/v4l2_m2m.h>
#include <nuttx/wqueue.h>""",
    """#include <pthread.h>
#include <semaphore.h>
#include <sched.h>

#include <nuttx/kmalloc.h>
#include <nuttx/video/v4l2_m2m.h>""",
    "includes")

