#!/usr/bin/env python3
"""Carry m.offset on every QBUF.

Root cause of the resets.  v4l2_m2m.c:508 rebuilds the kernel-side pointer on
each QBUF as

    vaddr = bufheap + buf->m.offset - offset

where `offset` is CAPTURE_BUF_OFFSET (1 << 30) for the capture queue and 0 for
the output queue.  So m.offset is not informational -- it is required input,
and QUERYBUF is where the application is told what to pass.

This code zeroed the whole struct before re-queueing, so m.offset arrived as 0
and the driver was handed bufheap - 0x40000000 for capture buffers, which is
outside RAM.  Encoding into it took the AP down, its heartbeat stopped, and CP
asserted six seconds later.  Output buffers came back as bufheap regardless of
index, so every frame read buffer 0.

The first pass through the pool worked because the initial QBUF reuses the
struct QUERYBUF just filled in, which still had the right offset.  That is why
exactly the third frame died: with two buffers per queue, it is the first one
to be re-queued.
"""

import sys

P = ("/home/mi/vela_competition_ap_console_dev/contest/"
     "contest2026_264_VelaSightsuixingAIzhinengyanjing/app/jpeg_test/"
     "jpeg_test_main.c")

src = open(P).read()
edits = []


def sub(old, new, label):
    global src
    n = src.count(old)
    if n != 1:
        print("FAIL [%s]: found %d, expected 1" % (label, n))
        sys.exit(1)
    src = src.replace(old, new, 1)
    edits.append(label)


# Remember what QUERYBUF said, per buffer.
sub("""struct jpeg_test_buf_s
{
  void   *addr;
  size_t  length;
};""",
    """struct jpeg_test_buf_s
{
  void     *addr;
  size_t    length;

  /* What QUERYBUF reported.  Required on every subsequent QBUF: the driver
   * rebuilds its pointer from it, so dropping it corrupts the address.
   */

  uint32_t  offset;
};""",
    "buf struct")

sub("""      bufs[i].length = buf.length;
      bufs[i].addr   = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                            MAP_SHARED, ctx->fd, buf.m.offset);""",
    """      bufs[i].length = buf.length;
      bufs[i].offset = buf.m.offset;
      bufs[i].addr   = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                            MAP_SHARED, ctx->fd, buf.m.offset);""",
    "record offset")

# Output queue: first queue-up of each frame.
sub("""      memset(&buf, 0, sizeof(buf));
      buf.type      = V4L2_BUF_TYPE_VIDEO_OUTPUT;
      buf.memory    = V4L2_MEMORY_MMAP;
      buf.index     = slot;
      buf.bytesused = rawsize;""",
    """      memset(&buf, 0, sizeof(buf));
      buf.type      = V4L2_BUF_TYPE_VIDEO_OUTPUT;
      buf.memory    = V4L2_MEMORY_MMAP;
      buf.index     = slot;
      buf.m.offset  = ctx.out[slot].offset;
      buf.bytesused = rawsize;""",
    "output qbuf")

# Capture queue: hand the buffer back after reading the JPEG out of it.
sub("""      memset(&buf, 0, sizeof(buf));
      buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory = V4L2_MEMORY_MMAP;
      buf.index  = dequeued;""",
    """      memset(&buf, 0, sizeof(buf));
      buf.type     = V4L2_BUF_TYPE_VIDEO_CAPTURE;
      buf.memory   = V4L2_MEMORY_MMAP;
      buf.index    = dequeued;
      buf.m.offset = ctx.cap[dequeued].offset;""",
    "capture requeue")

open(P, "w").write(src)
