      uint32_t ms = TICK2MSEC(clock_systime_ticks() - start);
      printf("gc9d01_fb: update %u: %d bytes in %ums (%u frames on bus)\n",
             (unsigned int)g_updates, GC9D01_FBLEN, (unsigned int)ms,
             (unsigned int)bk7258_qspi1_lcd_frame_count());
    }
  return OK;
}
