"""Report bar samples as RGB with a delta, not as an equality test.

JPEG is lossy, so exact equality never holds and flagging every bar as
"differs" buries the signal it was meant to show.  What matters is how far off
each bar is: a couple of levels is compression, a swapped bar is off by a
hundred.
"""

import sys

P = ("/home/mi/vela_competition_ap_console_dev/contest/"
     "contest2026_264_VelaSightsuixingAIzhinengyanjing/app/jpeg_test/"
     "jpeg_test_main.c")

