 * Name: jpeg_test_unpack565
 *
 * Description:
 *   RGB565 back to 8-bit channels, so differences can be read in the units
 *   the source was written in.
 *
 ****************************************************************************/

static void jpeg_test_unpack565(uint16_t px, int *r, int *g, int *b)
{
  *r = (int)((px >> 11) & 0x1f) * 8;
  *g = (int)((px >> 5) & 0x3f) * 4;
  *b = (int)(px & 0x1f) * 8;
}

