#!/usr/bin/env python3
"""Fall back to a single buffer per queue when two will not fit.

The board's PSRAM heap is 2.9 MB and the ramdisk permanently claims 2 MB of
it, leaving about 917 KB.  Two 640x480 I420 buffers plus two JPEG buffers need
roughly 1.54 MB, so REQBUFS fails with ENOMEM and the largest frame size
cannot be tested at all.  One buffer per queue needs about 772 KB and fits.

A single buffer serialises the pipeline -- the encoder cannot start the next
frame while the application still holds the previous one -- which costs
throughput but nothing in correctness, and a test tool that reports a smaller
number is better than one that refuses to run.
"""

import sys

P = ("/home/mi/vela_competition_ap_console_dev/contest/"
     "contest2026_264_VelaSightsuixingAIzhinengyanjing/app/jpeg_test/"
     "jpeg_test_main.c")

src = open(P).read()
edits = []


def sub(old, new, label):
    global src
    n = src.count(old)
    if n != 1:
        print("FAIL [%s]: found %d, expected 1" % (label, n))
        sys.exit(1)
    src = src.replace(old, new, 1)
    edits.append(label)


sub("""      printf("jpeg_test: REQBUFS(%s) failed: %d\\n",
             V4L2_TYPE_IS_OUTPUT(type) ? "output" : "capture", errno);
      return -errno;
    }""",
    """      if (errno != ENOMEM || req.count <= 1)
        {
          printf("jpeg_test: REQBUFS(%s) failed: %d\\n",
                 V4L2_TYPE_IS_OUTPUT(type) ? "output" : "capture", errno);
          return -errno;
        }

      /* Out of pool memory for the pipelined case.  One buffer per queue
       * still works, it just cannot overlap the next frame with the
       * application holding the previous one.
       */

      printf("jpeg_test: %s pool needs %lu buffers, retrying with 1\\n",
             V4L2_TYPE_IS_OUTPUT(type) ? "output" : "capture",
             (unsigned long)req.count);

      memset(&req, 0, sizeof(req));
      req.type   = type;
      req.memory = V4L2_MEMORY_MMAP;
      req.count  = 1;

      if (ioctl(ctx->fd, VIDIOC_REQBUFS, &req) < 0)
        {
          printf("jpeg_test: REQBUFS(%s) failed even with 1: %d\\n",
                 V4L2_TYPE_IS_OUTPUT(type) ? "output" : "capture", errno);
          return -errno;
        }
    }""",
    "reqbufs fallback")

open(P, "w").write(src)
print("applied %d edits" % len(edits))
for e in edits:
    print("  - " + e)

