 ****************************************************************************/

static int jpeg_test_cam(int quality, bool display, bool bswap)
{
  uint32_t width = 0;
  uint32_t height = 0;
  uint8_t *frame;
  int ret;

  frame = jpeg_test_capture(&width, &height);
